const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);const products=[{id:1,name:'Solstice',shape:'Ovale',carat:1.5,price:6800,origin:'Naturel',color:'G',clarity:'VS1',type:'bagues',metal:'Or jaune 750‰',image:'ring-1.jpg'},{id:2,name:'Épure',shape:'Brillant',carat:1,price:4900,origin:'Naturel',color:'F',clarity:'VS2',type:'bagues',metal:'Platine 950‰',image:'ring-2.jpg'},{id:3,name:'Héritage',shape:'Émeraude',carat:2,price:5200,origin:'Laboratoire',color:'E',clarity:'VVS2',type:'bagues',metal:'Or jaune 750‰',image:'ring-3.jpg'},{id:4,name:'Éclosion',shape:'Poire',carat:1.2,price:3100,origin:'Laboratoire',color:'F',clarity:'VS1',type:'bagues',metal:'Platine 950‰',image:'ring-4.jpg'},{id:5,name:'Lumière 1.00',shape:'Brillant',carat:1,price:3600,origin:'Naturel',color:'G',clarity:'VS1',type:'diamants',image:'hero.jpg'},{id:6,name:'Lumière 2.00',shape:'Brillant',carat:2,price:2400,origin:'Laboratoire',color:'E',clarity:'VVS2',type:'diamants',image:'hero.jpg'}];
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}let cart=read('emeraude-cart',[]),favorites=read('emeraude-favorites',[]);cart=cart.filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0);favorites=favorites.filter(x=>products.some(p=>p.id===x));let home=$('#main').innerHTML;const dialog=$('#dialog');let toastTimer;
function save(){try{localStorage.setItem('emeraude-cart',JSON.stringify(cart));localStorage.setItem('emeraude-favorites',JSON.stringify(favorites))}catch{}$('#cart-count').textContent=cart.reduce((n,x)=>n+x.qty,0)}
function toast(t){$('.toast').textContent=t;$('.toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),3000)}
function modal(html){$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal()}$('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function card(p){return `<article class="product"><button class="favorite" data-fav="${p.id}" aria-label="${favorites.includes(p.id)?'Retirer des':'Ajouter aux'} favoris : ${p.name}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'♥':'♡'}</button><a class="product-image" href="#produit/${p.id}"><img src="assets/${p.image}" alt="${p.type==='bagues'?'Bague':'Diamant'} ${p.name}, taille ${p.shape.toLowerCase()}" width="600" height="690" loading="lazy"></a><h3><a href="#produit/${p.id}">${p.name}</a></h3><p>${p.shape} · ${p.carat.toLocaleString('fr-FR')} ct · ${p.origin==='Naturel'?'Naturel':'Laboratoire'}</p><p class="price">${money(p.price)}</p></article>`}
const shapes=['Brillant','Ovale','Émeraude','Poire','Coussin'];const paths=['<circle cx="35" cy="35" r="26"/><path d="m16 17 38 0 8 28-27 16L8 45Zm19-8v52M9 35h52M16 17l38 36m0-36L16 53"/>','<ellipse cx="35" cy="35" rx="20" ry="29"/><path d="m35 6 20 29-20 29-20-29Zm0 0v58M15 35h40"/>','<path d="M20 6h30l10 12v34L50 64H20L10 52V18ZM24 14h22l6 8v26l-6 8H24l-6-8V22Zm0 0 22 42m0-42L24 56"/>','<path d="M35 5C22 23 11 31 13 45c3 26 41 26 44 0 2-14-9-22-22-40Zm0 0v59M13 45l22-20 22 20-22 19Z"/>','<rect x="9" y="9" width="52" height="52" rx="15"/><path d="m24 13 22 0 11 11v22L46 57H24L13 46V24Zm0 0 22 44m0-44L24 57M13 24l44 22m0-22L13 46"/>'];
const extra=`<div class="band"><span>DIAMANTS NATURELS & DE LABORATOIRE</span><span>CRÉATION SUR MESURE</span><span>L’ART DU DÉTAIL</span></div><section class="section shapes"><p class="eyebrow">À CHAQUE TAILLE, UNE PERSONNALITÉ</p><h2>Trouvez votre éclat.</h2><div class="shape-list">${shapes.map((s,i)=>`<button data-shape="${s}"><svg viewBox="0 0 70 70" aria-hidden="true">${paths[i]}</svg>${s}</button>`).join('')}</div></section><section class="atelier" id="sur-mesure"><div class="atelier-image" role="img" aria-label="Diamant brillant posé sur une pierre vert profond"></div><div class="atelier-copy"><p class="eyebrow">LE SUR-MESURE</p><h2>Votre histoire.<br>Notre inspiration.</h2><p>Une pierre, une ligne, une intention. Imaginez une bague qui ne ressemble qu’à vous, du choix du diamant à la nuance du métal.</p><a class="button gold" href="#rendez-vous">Imaginer ma création</a></div></section><section class="section fourcs" id="les-4c"><div><p class="eyebrow">COMPRENDRE POUR MIEUX CHOISIR</p><h2>La beauté,<br>dans ses nuances.</h2><p>Quatre critères pour regarder un diamant autrement.</p></div><div><details open><summary>01 — Le carat</summary><p>Le carat mesure le poids : 1 carat équivaut à 0,20 gramme. Les proportions et la forme influencent aussi la dimension apparente d’une pierre.</p></details><details><summary>02 — La couleur</summary><p>Pour les diamants blancs, l’échelle usuelle va de D, incolore, à Z, présentant une teinte plus marquée. La perception dépend aussi du métal et de la lumière.</p></details><details><summary>03 — La pureté</summary><p>La pureté décrit les inclusions et les caractéristiques de surface observées sous grossissement. VVS, VS et SI désignent différents niveaux ; leur visibilité varie selon la pierre.</p></details><details><summary>04 — La taille</summary><p>Au-delà de sa forme, la qualité de taille exprime le travail des proportions, de la symétrie et du poli. C’est elle qui révèle le jeu de la lumière.</p></details></div></section><section class="section commitments" id="maison"><p class="eyebrow">L’ESPRIT DE LA MAISON</p><h2>L’essentiel, sans compromis.</h2><div class="commitment-grid"><div><h3>La clarté du choix</h3><p>Une distinction lisible entre diamants naturels et de laboratoire, pour choisir en connaissance de cause.</p></div><div><h3>Le sens du détail</h3><p>Des lignes épurées, des proportions justes. Une vision de la joaillerie qui laisse toute sa place à la pierre.</p></div><div><h3>Une relation de confiance</h3><p>Des caractéristiques et des prix explicites. Aucune certification ni provenance réelle n’est revendiquée dans cette démonstration.</p></div></div></section>`;
function renderHome(){ $('#main').innerHTML=home+extra;$('#featured').innerHTML=products.slice(0,4).map(card).join('') }
function catalog(type='tous',shape='',onlyFavorites=false){$('#main').innerHTML=`<div class="page-intro"><p class="eyebrow">LA COLLECTION LE DIAMANT VERT</p><h1>${onlyFavorites?'Vos coups de cœur':type==='bagues'?'L’art du solitaire.':type==='diamants'?'La lumière à l’état pur.':'Les pièces d’exception.'}</h1><p>${onlyFavorites?'Une sélection personnelle, conservée sur cet appareil.':'Des pièces de démonstration pour découvrir votre signature.'}</p></div><section class="catalog-layout"><div class="filters"><label>Origine<select id="origin"><option value="">Toutes les origines</option><option>Naturel</option><option>Laboratoire</option></select></label><label>Prix maximum<select id="price"><option value="">Tous les prix</option><option value="3000">3 000 €</option><option value="5000">5 000 €</option><option value="7000">7 000 €</option></select></label><label>Caratage<select id="carat"><option value="">Tous les poids</option><option value="1">Jusqu’à 1 ct</option><option value="1.5">1,01 à 1,50 ct</option><option value="2">Plus de 1,50 ct</option></select></label><label>Taille<select id="shape"><option value="">Toutes les tailles</option>${shapes.map(s=>`<option ${shape===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Couleur<select id="color"><option value="">Toutes</option><option>E</option><option>F</option><option>G</option></select></label><label>Pureté<select id="clarity"><option value="">Toutes</option><option>VVS2</option><option>VS1</option><option>VS2</option></select></label></div><div class="result-bar"><span id="result-count" role="status"></span><button class="text-link" id="reset">Réinitialiser les filtres</button></div><div class="products" id="results"></div></section>`;
// Explicit option markup keeps every colour filter available.
$('#color').innerHTML='<option value="">Toutes</option><option>E</option><option>F</option><option>G</option>';
function filter(){const origin=$('#origin').value,price=+$('#price').value,carat=$('#carat').value,shape=$('#shape').value,color=$('#color').value,clarity=$('#clarity').value;const list=products.filter(p=>(type==='tous'||p.type===type)&&(!onlyFavorites||favorites.includes(p.id))&&(!origin||p.origin===origin)&&(!price||p.price<=price)&&(!shape||p.shape===shape)&&(!color||p.color===color)&&(!clarity||p.clarity===clarity)&&(!carat||(carat==='1'?p.carat<=1:carat==='1.5'?p.carat>1&&p.carat<=1.5:p.carat>1.5)));$('#result-count').textContent=`${list.length} pièce${list.length>1?'s':''}`;$('#results').innerHTML=list.length?list.map(card).join(''):'<p class="empty">Aucune pièce ne correspond à votre sélection. Essayez d’autres filtres.</p>'}document.querySelectorAll('.filters select').forEach(s=>s.onchange=filter);$('#reset').onclick=()=>{document.querySelectorAll('.filters select').forEach(s=>s.value='');filter()};filter();decorateCatalog(type,onlyFavorites)}
function product(id){const p=products.find(p=>p.id===+id);if(!p){$('#main').innerHTML='<section class="section"><h1>Pièce introuvable</h1><a href="#catalogue/tous">Revenir à la collection</a></section>';return}document.title=`${p.name} — LE DIAMANT VERT`;$('#main').innerHTML=`<a class="back" href="#catalogue/${p.type}">Collection / ${p.name}</a><section class="detail"><div><button class="gallery-main" data-zoom="${p.image}" aria-label="Agrandir la photographie de ${p.name}"><img src="assets/${p.image}" alt="${p.name}, vue d’ensemble"></button><div class="thumbnails"><button data-view="full" aria-label="Vue d’ensemble"><img src="assets/${p.image}" alt="Vue d’ensemble"></button><button data-view="close" aria-label="Détail de la pierre"><img src="assets/${p.image}" alt="Détail" style="transform:scale(1.0);object-position:center"></button></div><p class="notice">Vue d’ensemble et détail agrandi · Visuel de synthèse non contractuel.</p></div><div class="detail-copy"><p class="eyebrow">${p.type==='bagues'?'BAGUE SOLITAIRE':'DIAMANT NON MONTÉ'} · ${p.origin.toUpperCase()}</p><h1>${p.name}</h1><p>Une lumière singulière, une élégance intemporelle. ${p.type==='bagues'?'Un solitaire aux lignes essentielles, pensé autour de la pierre.':'Un diamant brillant pour donner naissance à votre création.'}</p><p class="price">${money(p.price)}</p><p class="notice">Disponible dans le catalogue de démonstration · Stock réel non connecté.</p><table class="details-table"><tbody>${[['Origine',p.origin==='Naturel'?'Diamant naturel':'Diamant de laboratoire'],['Taille',p.shape],['Poids du diamant',p.carat.toLocaleString('fr-FR')+' ct'],['Couleur',p.color],['Pureté',p.clarity],['Certification','Non fournie — démonstration']].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('')}</tbody></table>${p.type==='bagues'?`<div class="form-grid"><label class="field">Métal<select id="metal"><option>${p.metal}</option><option>${p.metal.startsWith('Or')?'Platine 950‰':'Or jaune 750‰'}</option><option>Or rose 750‰</option></select></label><label class="field">Tour de doigt<select id="size">${[48,50,52,54,56,58,60,62].map(n=>`<option ${n===54?'selected':''}>${n}</option>`).join('')}</select></label></div><p class="notice">Prix de démonstration identique pour les métaux. Le visuel représente ${p.metal.toLowerCase()}.</p>`:''}<button class="button dark" data-add="${p.id}" style="width:100%">Ajouter au panier</button><button class="text-link" data-fav="${p.id}" style="margin-top:20px">${favorites.includes(p.id)?'Retirer des favoris':'Ajouter à mes favoris'}</button></div></section>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{$('.gallery-main img').style.transform=b.dataset.view==='close'?'scale(1.65)':'none';$('.gallery-main img').alt=b.dataset.view==='close'?`${p.name}, détail agrandi`:`${p.name}, vue d’ensemble`})}
function add(id,metal,size){const p=products.find(p=>p.id===Number(id));if(!p)throw Error('Pièce inconnue');metal=metal||'';size=size||'';if(p.type==='bagues'&&(!['Or jaune 750‰','Platine 950‰','Or rose 750‰'].includes(metal)||![48,50,52,54,56,58,60,62].includes(+size)))throw Error('Veuillez choisir un métal et un tour de doigt valides.');let item=cart.find(x=>x.id===p.id&&x.metal===metal&&x.size===size);if(item)item.qty++;else cart.push({id:p.id,metal:metal||'',size:size||'',qty:1});save();toast('La pièce a été ajoutée à votre panier.');return {pieces:cart.reduce((n,x)=>n+x.qty,0)}}
function showCart(){modal(`<p class="eyebrow">VOTRE SÉLECTION</p><h2>Le panier</h2>${cart.length?cart.map((x,i)=>{let p=products.find(p=>p.id===x.id);return `<div class="cart-row"><img src="assets/${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${x.metal}${x.size?' · Taille '+x.size:''}</p><p>${money(p.price)}</p><button data-remove="${i}" class="text-link">Retirer</button></div><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Diminuer la quantité de ${p.name}">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Augmenter la quantité de ${p.name}">+</button></div></div>`}).join('')+`<div class="cart-total"><span>Total indicatif</span><strong>${money(cart.reduce((s,x)=>s+products.find(p=>p.id===x.id).price*x.qty,0))}</strong></div><p class="notice">Panier enregistré sur cet appareil. Boutique de démonstration : aucun paiement ni envoi de commande.</p><button class="button dark" data-action="checkout">Consulter le récapitulatif</button>`:'<p>Votre prochaine histoire reste à choisir.</p><a class="button dark" href="#catalogue/tous">Découvrir les pièces</a>'}`)}
function appointment(){ $('#main').innerHTML=`<section class="appointment"><p class="eyebrow">LE SUR-MESURE</p><h1>Tout commence<br>par une rencontre.</h1><p>Une taille de pierre, un métal, une idée. Préparez les premières lignes de votre projet.</p><p class="notice">Formulaire de démonstration : aucune donnée n’est transmise et aucun rendez-vous ne sera réservé.</p><form id="appointment"><div class="form-grid"><label class="field">Votre prénom<input name="name" required autocomplete="given-name" maxlength="60"></label><label class="field">Votre e-mail<input name="email" type="email" required autocomplete="email"></label></div><div class="form-grid"><label class="field">Votre projet<select name="project"><option>Créer une bague</option><option>Choisir un diamant</option><option>Découvrir la collection</option></select></label><label class="field">Date souhaitée<input name="date" type="date" min="${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}-${String(new Date().getDate()).padStart(2,'0')}" required></label></div><label class="field">Vos premières envies<textarea name="message" rows="4" placeholder="Une forme, un métal, une occasion…" maxlength="2000"></textarea></label><button class="button dark" type="submit">Prévisualiser ma demande</button></form></section>`;$('#appointment').onsubmit=e=>{e.preventDefault();modal('<p class="eyebrow">DÉMONSTRATION</p><h2>Votre projet prend forme.</h2><p>Votre formulaire est complet. Dans la boutique définitive, cette demande serait adressée à la Maison.</p><p><strong>Aucune demande n’a été envoyée et aucun rendez-vous n’est réservé.</strong></p><button class="button dark" data-action="close">Revenir à mon projet</button>')}}
function search(){modal('<p class="eyebrow">DÉCOUVRIR LA COLLECTION</p><h2>Votre recherche</h2><label for="search">Nom, taille ou origine du diamant</label><input id="search" class="search-input" type="search" placeholder="Ovale, Solstice, laboratoire…"><div class="search-results" aria-live="polite"></div>');$('#search').oninput=()=>{let q=$('#search').value.toLocaleLowerCase('fr');let list=products.filter(p=>`${p.name} ${p.shape} ${p.origin} ${p.type}`.toLocaleLowerCase('fr').includes(q));$('.search-results').innerHTML=list.length?list.map(p=>`<a href="#produit/${p.id}"><img src="assets/${p.image}" alt=""><span>${p.name}<br><small>${p.shape} · ${money(p.price)}</small></span></a>`).join(''):'<p>Aucune pièce trouvée. Essayez « brillant » ou « bague ».</p>'};$('#search').oninput();$('#search').focus()}
function route(){if(dialog.open)dialog.close();let [page,arg,shape]=location.hash.slice(1).split('/');document.title='LE DIAMANT VERT — L’exception, à votre mesure.';
if(page==='catalogue'){let decoded='';try{decoded=decodeURIComponent(shape||'')}catch{}catalog(['diamants','bagues','tous'].includes(arg)?arg:'tous',decoded)}
else if(page==='produit'){product(arg);enhanceProduct()}
else if(page==='favoris')catalog('tous','',true);
else if(page==='sur-mesure')bespokePage();
else if(page==='maison')housePage();
else if(page==='guide-diamants'||page==='les-4c')diamondGuide();
else if(page==='guide-tailles')sizeGuide();
else if(page==='contact')contactPage();
else if(page==='informations')practicalPage();
else if(page==='mentions-legales')legalPage();
else if(page==='confidentialite')legalPage(true);
else if(page==='rendez-vous'){appointment();document.title='Rendez-vous — Le Diamant Vert';if(window.creationBrief)$('#appointment textarea').value=window.creationBrief;}
else if(!page||['accueil','selection','main'].includes(page)){renderHome();if(page==='selection'){requestAnimationFrame(()=>document.getElementById(page)?.scrollIntoView());return}}
else{$('#main').innerHTML='<section class="section"><p class="eyebrow">LE DIAMANT VERT</p><h1>Page introuvable.</h1><a class="button dark" href="#accueil">Revenir à l’accueil</a></section>'}
document.querySelectorAll('header nav a').forEach(a=>{const current=a.hash===location.hash;a.toggleAttribute('aria-current',current);if(current)a.setAttribute('aria-current','page')});window.scrollTo(0,0);$('#main').tabIndex=-1;$('#main').focus({preventScroll:true})}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(e.target.closest('dialog a'))dialog.close();if(!b)return;if(b.dataset.origin){$('#origin').value=b.dataset.origin;$('#origin').dispatchEvent(new Event('change'));$('.filters').scrollIntoView({block:'start'});}if(b.dataset.fav){const id=+b.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save();if(b.classList.contains('favorite')){b.textContent=favorites.includes(id)?'♥':'♡';b.setAttribute('aria-pressed',favorites.includes(id));b.setAttribute('aria-label',`${favorites.includes(id)?'Retirer des':'Ajouter aux'} favoris : ${products.find(p=>p.id===id).name}`)}else b.textContent=favorites.includes(id)?'Retirer des favoris':'Ajouter à mes favoris';toast(favorites.includes(id)?'Pièce ajoutée aux favoris.':'Pièce retirée des favoris.');if(location.hash==='#favoris')catalog('tous','',true)}if(b.dataset.shape)location.hash='catalogue/tous/'+encodeURIComponent(b.dataset.shape);if(b.dataset.add)add(+b.dataset.add,$('#metal')?.value,$('#size')?.value);if(b.dataset.zoom)modal(`<img class="zoom-image" src="assets/${b.dataset.zoom}" alt="Photographie agrandie de la pièce">`);if(b.dataset.remove!==undefined){cart.splice(+b.dataset.remove,1);save();showCart()}if(b.dataset.qty!==undefined){let i=+b.dataset.qty;cart[i].qty+=+b.dataset.delta;if(cart[i].qty<=0)cart.splice(i,1);save();showCart()}switch(b.dataset.action){case 'cart':showCart();break;case 'favorites':location.hash='favoris';break;case 'search':search();break;case 'menu':modal('<nav class="mobile-nav" aria-label="Menu mobile"><a href="#catalogue/diamants">Diamants</a><a href="#catalogue/bagues">Bagues</a><a href="#sur-mesure">Sur mesure</a><a href="#maison">Notre Maison</a><a href="#contact">Contact</a></nav>');break;case 'close':dialog.close();break;case 'checkout':modal(`<p class="eyebrow">RÉCAPITULATIF DE DÉMONSTRATION</p><h2>Une sélection d’exception.</h2><p>${cart.reduce((n,x)=>n+x.qty,0)} pièce(s) · ${money(cart.reduce((n,x)=>n+products.find(p=>p.id===x.id).price*x.qty,0))}</p><p>Aucun paiement n’est disponible. Aucune commande n’a été passée. Votre sélection reste dans votre panier.</p><button class="button dark" data-action="cart">Revenir au panier</button>`);break;case 'legal':modal('<h2>En toute transparence.</h2><p>LE DIAMANT VERT est une maison imaginaire créée pour cette démonstration. Les produits, prix, caractéristiques et disponibilités sont illustratifs. Les images ont été générées pour ce site et ne représentent pas des pièces réelles.</p><h3>Vos données</h3><p>Le panier et les favoris sont conservés uniquement dans le stockage local de votre navigateur. Le formulaire n’envoie ni ne conserve vos coordonnées. Aucun outil de suivi publicitaire n’est intégré.</p><p>Ce site ne permet aucun paiement. Les informations commerciales et légales de l’exploitant devront être ajoutées avant toute vente réelle.</p><button class="text-link" data-action="clear">Effacer mon panier et mes favoris locaux</button>');break;case 'clear':cart=[];favorites=[];save();dialog.close();route();toast('Vos données locales ont été effacées.')}});
window.addEventListener('hashchange',route);save();route();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_collection',description:'Lire les pièces de démonstration de la collection LE DIAMANT VERT.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({products})},{name:'open_product',description:'Ouvrir la fiche d’une pièce, sans ajout au panier ni achat.',inputSchema:{type:'object',properties:{id:{type:'integer'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({id})=>{if(!Number.isInteger(id)||!products.some(p=>p.id===id))throw Error('Pièce inconnue');location.hash=`produit/${id}`;route();return {id,opened:true}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
